command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="4c67beb0396690b28b487879f2e016d0d7f4e919";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC UIA successor fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC UIA successor"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC UIA successor candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-uia-"+$env:GITHUB_RUN_ID)
if(Test-Path $temp){Remove-Item $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC UIA worktree add failed"}
 Set-Location $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "UNC UIA diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "UNC UIA FAST failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "UNC UIA Release build failed"}
 & python -X utf8 tools\winui\run_checks.py gui --area unc-copy-move --configuration Release
 if($LASTEXITCODE -ne 0){throw "UNC UIA focused GUI failed"}
 Write-Host "UNC_COPY_MOVE_UIA_FAST=PASS"
 Write-Host "UNC_COPY_MOVE_UIA_RELEASE_BUILD=PASS"
 Write-Host "UNC_COPY_MOVE_UIA_GUI=PASS"
 Write-Host "UNC_COPY_MOVE_REUSED_M22_RELEASE_RUN=37553699165"
 Write-Host "UNC_COPY_MOVE_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
 Set-Location $repo
 if(Test-Path $temp){& git worktree remove --force $temp}
 & git worktree prune
}
